"use client";

import * as React from "react";
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";

import { cn } from "@/lib/utils";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

const Tabs = TabsPrimitive.Root;

/**
 * Airy docs TabsList: a row of labels standing on the page hairline, the
 * way docs pages switch between examples.
 */
const TabsList = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.List.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.List
    ref={ref}
    data-slot="tabs-list"
    className={cn(
      "inline-flex items-center gap-4 border-b border-border text-muted-foreground",
      className,
    )}
    {...props}
  />
));
TabsList.displayName = "TabsList";

/**
 * Airy docs TabsTrigger: grey text that darkens on hover. The active tab
 * turns to full ink and a 0.125rem green bar sits under it on the hairline.
 */
const TabsTrigger = React.forwardRef<
  HTMLButtonElement,
  WithClassName<TabsPrimitive.Tab.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Tab
    ref={ref}
    data-slot="tabs-trigger"
    className={cn(
      "relative -mb-px inline-flex h-10 shrink-0 items-center justify-center gap-1.5 whitespace-nowrap border-b-2 border-transparent px-0.5",
      "text-sm font-medium text-muted-foreground",
      "transition-colors duration-fast ease-out hover:text-foreground",
      "data-[active]:border-primary data-[active]:text-foreground",
      "rounded-t-sm outline-none focus-visible:ring-3 focus-visible:ring-ring",
      "data-[disabled]:cursor-not-allowed data-[disabled]:text-(--foreground-disabled)",
      "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
      className,
    )}
    {...props}
  />
));
TabsTrigger.displayName = "TabsTrigger";

/** Airy docs TabsContent: the active panel, set below the tab row. */
const TabsContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.Panel.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Panel
    ref={ref}
    data-slot="tabs-content"
    className={cn(
      "mt-4 rounded-md outline-none focus-visible:ring-3 focus-visible:ring-ring",
      className,
    )}
    {...props}
  />
));
TabsContent.displayName = "TabsContent";

export { Tabs, TabsList, TabsTrigger, TabsContent };
